-- ------------------------------------------------------------ ab_checkouts
CREATE TABLE IF NOT EXISTS `ab_checkouts` (
  `id` varchar(64) NOT NULL,
  `token` varchar(191) DEFAULT NULL,
  `cart_token` varchar(191) DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `completed_at` datetime DEFAULT NULL,
  `name` varchar(255) DEFAULT NULL,
  `phone` varchar(32) DEFAULT NULL,
  `email` varchar(191) DEFAULT NULL,
  `city` varchar(120) DEFAULT NULL,
  `items` mediumtext DEFAULT NULL,
  `total` double DEFAULT 0,
  `url` text DEFAULT NULL,
  `status` varchar(16) DEFAULT 'new',
  `contacted_by` bigint(20) unsigned DEFAULT NULL,
  `contacted_at` datetime DEFAULT NULL,
  `contacts` int(11) DEFAULT 0,
  `last_outcome` varchar(32) DEFAULT NULL,
  `note` text DEFAULT NULL,
  `recovered_order` varchar(64) DEFAULT NULL,
  `recovered_name` varchar(64) DEFAULT NULL,
  `recovered_value` double DEFAULT NULL,
  `recovered_at` datetime DEFAULT NULL,
  `recovered_by` bigint(20) unsigned DEFAULT NULL,
  `recovered_how` varchar(120) DEFAULT NULL,
  `lost_reason` varchar(191) DEFAULT NULL,
  `lost_at` datetime DEFAULT NULL,
  `lost_by` bigint(20) unsigned DEFAULT NULL,
  `src` varchar(16) DEFAULT NULL,
  `ingested_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `ix_ab_status` (`status`,`updated_at`),
  KEY `ab_checkouts_token_index` (`token`),
  KEY `ab_checkouts_phone_index` (`phone`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------ ab_events
CREATE TABLE IF NOT EXISTS `ab_events` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `checkout_id` varchar(64) DEFAULT NULL,
  `user_id` bigint(20) unsigned DEFAULT NULL,
  `kind` varchar(20) DEFAULT NULL,
  `outcome` varchar(32) DEFAULT NULL,
  `note` text DEFAULT NULL,
  `at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `ix_ab_ev` (`checkout_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------ ab_orders
CREATE TABLE IF NOT EXISTS `ab_orders` (
  `id` varchar(64) NOT NULL,
  `name` varchar(64) DEFAULT NULL,
  `checkout_token` varchar(191) DEFAULT NULL,
