-- ------------------------------------------------------------ acc_journals
CREATE TABLE IF NOT EXISTS `acc_journals` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `date` varchar(10) NOT NULL,
  `memo` text DEFAULT NULL,
  `source` varchar(60) NOT NULL,
  `source_id` varchar(191) NOT NULL,
  `ref` varchar(60) DEFAULT NULL,
  `kind` varchar(10) DEFAULT NULL,
  `file_id` varchar(64) DEFAULT NULL,
  `user_id` bigint(20) unsigned DEFAULT NULL,
  `amount` double NOT NULL DEFAULT 0,
  `meta` mediumtext DEFAULT NULL,
  `voided` tinyint(1) NOT NULL DEFAULT 0,
  `void_reason` text DEFAULT NULL,
  `voided_by` bigint(20) unsigned DEFAULT NULL,
  `voided_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ux_acc_journals_src` (`source`,`source_id`),
  KEY `ix_acc_journals_date` (`date`),
  KEY `ix_acc_journals_ref` (`ref`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------ acc_lines
CREATE TABLE IF NOT EXISTS `acc_lines` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `journal_id` bigint(20) unsigned NOT NULL,
  `account_id` bigint(20) unsigned NOT NULL,
  `debit` double NOT NULL DEFAULT 0,
  `credit` double NOT NULL DEFAULT 0,
  `party` varchar(191) DEFAULT NULL,
  `memo` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_acc_lines_j` (`journal_id`),
  KEY `ix_acc_lines_a` (`account_id`),
  KEY `ix_acc_lines_party` (`party`),
  CONSTRAINT `acc_lines_account_id_foreign` FOREIGN KEY (`account_id`) REFERENCES `acc_accounts` (`id`),
  CONSTRAINT `acc_lines_journal_id_foreign` FOREIGN KEY (`journal_id`) REFERENCES `acc_journals` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

