) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------ tk_refunds
CREATE TABLE IF NOT EXISTS `tk_refunds` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `ticket_id` bigint(20) unsigned DEFAULT NULL,
  `exchange_id` bigint(20) unsigned DEFAULT NULL,
  `order_id` varchar(64) DEFAULT NULL,
  `order_name` varchar(64) DEFAULT NULL,
  `phone` varchar(32) DEFAULT NULL,
  `cust_name` varchar(191) DEFAULT NULL,
  `method` varchar(40) DEFAULT NULL,
  `amount` double DEFAULT NULL,
  `account_details` text DEFAULT NULL,
  `reason` text DEFAULT NULL,
  `status` varchar(20) DEFAULT 'pending',
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `approved_by` bigint(20) unsigned DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `paid_by` bigint(20) unsigned DEFAULT NULL,
  `paid_at` datetime DEFAULT NULL,
  `paid_ref` varchar(191) DEFAULT NULL,
  `rejected_by` bigint(20) unsigned DEFAULT NULL,
  `rejected_at` datetime DEFAULT NULL,
  `reject_reason` text DEFAULT NULL,
  `posted` tinyint(1) DEFAULT 0,
  `post_error` text DEFAULT NULL,
  `journal_id` varchar(64) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_tk_ref_phone` (`phone`),
  KEY `ix_tk_ref_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------ tk_tickets
CREATE TABLE IF NOT EXISTS `tk_tickets` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `type` varchar(60) DEFAULT NULL,
  `channel` varchar(40) DEFAULT NULL,
  `subject` varchar(255) DEFAULT NULL,
  `order_id` varchar(64) DEFAULT NULL,
  `order_name` varchar(64) DEFAULT NULL,
  `phone` varchar(32) DEFAULT NULL,
  `cust_name` varchar(191) DEFAULT NULL,
  `tracking` varchar(120) DEFAULT NULL,
  `sku` varchar(120) DEFAULT NULL,
  `priority` varchar(16) DEFAULT 'normal',
  `assignee` bigint(20) unsigned DEFAULT NULL,
  `status` varchar(20) DEFAULT 'open',
  `auto` tinyint(1) DEFAULT 0,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp(),
  `due_at` datetime DEFAULT NULL,
  `first_response_at` datetime DEFAULT NULL,
  `resolved_at` datetime DEFAULT NULL,
  `closed_at` datetime DEFAULT NULL,
  `resolution` varchar(120) DEFAULT NULL,
  `resolution_note` text DEFAULT NULL,
  `resolved_by` bigint(20) unsigned DEFAULT NULL,
  `reopened` int(11) DEFAULT 0,
  `fault_dept` varchar(20) DEFAULT NULL,
  `fault_user_id` bigint(20) unsigned DEFAULT NULL,
  `fault_reason` varchar(191) DEFAULT NULL,
  `fault_note` text DEFAULT NULL,
  `fault_cost` double DEFAULT NULL,
  `fault_by` bigint(20) unsigned DEFAULT NULL,
  `fault_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_tk_order` (`order_id`),
  KEY `ix_tk_phone` (`phone`),
  KEY `ix_tk_assignee` (`assignee`),
  KEY `ix_tk_status` (`status`),
  KEY `ix_tk_fault` (`fault_user_id`,`resolved_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------ user_permissions
CREATE TABLE IF NOT EXISTS `user_permissions` (
  `user_id` bigint(20) unsigned NOT NULL,
  `permission_key` varchar(40) NOT NULL,
  `effect` enum('grant','revoke') NOT NULL,
  PRIMARY KEY (`user_id`,`permission_key`),
  KEY `user_permissions_permission_key_foreign` (`permission_key`),
  CONSTRAINT `user_permissions_permission_key_foreign` FOREIGN KEY (`permission_key`) REFERENCES `permissions` (`key`) ON DELETE CASCADE,
  CONSTRAINT `user_permissions_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------ users
CREATE TABLE IF NOT EXISTS `users` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(120) NOT NULL,
  `username` varchar(64) NOT NULL,
  `email` varchar(191) DEFAULT NULL,
  `password` varchar(255) NOT NULL,
  `role` varchar(32) NOT NULL,
  `perms` text DEFAULT NULL,
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `registered_via` varchar(20) NOT NULL DEFAULT 'admin',
  `remember_token` varchar(100) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT NULL,
  `last_login` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `users_username_unique` (`username`),
  UNIQUE KEY `users_email_unique` (`email`),
  KEY `users_role_index` (`role`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------ webhook_events
CREATE TABLE IF NOT EXISTS `webhook_events` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `webhook_id` varchar(100) NOT NULL,
  `topic` varchar(80) NOT NULL,
  `shop_domain` varchar(191) DEFAULT NULL,
  `resource_id` varchar(64) DEFAULT NULL,
  `api_version` varchar(20) DEFAULT NULL,
  `payload` mediumtext DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'received',
  `attempts` int(10) unsigned NOT NULL DEFAULT 0,
  `error` text DEFAULT NULL,
  `triggered_at` datetime DEFAULT NULL,
  `received_at` datetime NOT NULL DEFAULT current_timestamp(),
  `processed_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `webhook_events_webhook_id_unique` (`webhook_id`),
  KEY `webhook_events_topic_index` (`topic`),
  KEY `webhook_events_resource_id_index` (`resource_id`),
  KEY `webhook_events_status_index` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------ wms_count_scans
CREATE TABLE IF NOT EXISTS `wms_count_scans` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `count_id` bigint(20) unsigned DEFAULT NULL,
  `slot` varchar(64) DEFAULT NULL,
  `sku` varchar(120) DEFAULT NULL,
  `result` varchar(20) DEFAULT NULL,
  `recorded_loc` varchar(60) DEFAULT NULL,
  `sold` tinyint(1) DEFAULT 0,
  `moved` tinyint(1) DEFAULT 0,
  `user_id` bigint(20) unsigned DEFAULT NULL,
  `at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `wms_count_scans_count_id_sku_unique` (`count_id`,`sku`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------ wms_count_slots
CREATE TABLE IF NOT EXISTS `wms_count_slots` (
  `count_id` bigint(20) unsigned NOT NULL,
  `slot` varchar(64) NOT NULL,
  `done_at` datetime DEFAULT NULL,
  `user_id` bigint(20) unsigned DEFAULT NULL,
  PRIMARY KEY (`count_id`,`slot`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------ wms_counts
CREATE TABLE IF NOT EXISTS `wms_counts` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(191) DEFAULT NULL,
  `rack` varchar(60) DEFAULT NULL,
  `slots` mediumtext DEFAULT NULL,
  `assigned_to` bigint(20) unsigned DEFAULT NULL,
  `due` varchar(10) DEFAULT NULL,
  `status` varchar(20) DEFAULT 'open',
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `started_at` datetime DEFAULT NULL,
  `finished_at` datetime DEFAULT NULL,
  `approved_by` bigint(20) unsigned DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `summary` mediumtext DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------ wms_damage
CREATE TABLE IF NOT EXISTS `wms_damage` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `sku` varchar(120) DEFAULT NULL,
  `title` varchar(500) DEFAULT NULL,
  `reason` varchar(60) DEFAULT NULL,
  `photo` text DEFAULT NULL,
  `found_at` varchar(191) DEFAULT NULL,
  `note` text DEFAULT NULL,
  `cost` double DEFAULT NULL,
  `status` varchar(20) DEFAULT 'reported',
  `reported_by` bigint(20) unsigned DEFAULT NULL,
