  `approved_by` bigint(20) unsigned DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `post_error` text DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------ wms_grn
CREATE TABLE IF NOT EXISTS `wms_grn` (
  `lot` varchar(120) NOT NULL,
  `expected` int(11) DEFAULT NULL,
  `good` int(11) DEFAULT NULL,
  `damaged` int(11) DEFAULT NULL,
  `diff` int(11) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `photos` text DEFAULT NULL,
  `per_piece` double DEFAULT NULL,
  `value` double DEFAULT NULL,
  `received_by` bigint(20) unsigned DEFAULT NULL,
  `received_at` datetime DEFAULT NULL,
  `posted` tinyint(1) DEFAULT 0,
  `post_error` text DEFAULT NULL,
  PRIMARY KEY (`lot`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------ wms_missing
CREATE TABLE IF NOT EXISTS `wms_missing` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `sku` varchar(120) DEFAULT NULL,
  `title` varchar(500) DEFAULT NULL,
  `count_id` bigint(20) unsigned DEFAULT NULL,
  `last_loc` varchar(60) DEFAULT NULL,
  `cost` double DEFAULT NULL,
  `status` varchar(20) DEFAULT 'open',
