  `active` tinyint(1) DEFAULT 1,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`code`),
  KEY `ix_wms_slots_rack` (`rack`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------ wms_transfer_items
CREATE TABLE IF NOT EXISTS `wms_transfer_items` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `transfer_id` bigint(20) unsigned DEFAULT NULL,
  `sku` varchar(120) DEFAULT NULL,
  `from_loc` varchar(60) DEFAULT NULL,
  `received` tinyint(1) DEFAULT 0,
  `extra` tinyint(1) DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `ix_wms_ti` (`transfer_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------ wms_transfers
CREATE TABLE IF NOT EXISTS `wms_transfers` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `dest` varchar(20) DEFAULT NULL,
  `note` text DEFAULT NULL,
  `status` varchar(20) DEFAULT 'sent',
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `sent_at` datetime DEFAULT current_timestamp(),
  `received_by` bigint(20) unsigned DEFAULT NULL,
  `received_at` datetime DEFAULT NULL,
  `discrepancy` text DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

